// ini adalah template script

helpers.log("----variable binding----")

helpers.log(binding_1)
helpers.log(JSON.stringify(binding_2.value));

const nowTs = msg.ts || helpers.now();

const eventPath = `${MachineAlarmAttribute.path}/Event/Alarm/MachineSpeedHigh`;
const speed = Number(MachinePresentValue?.value ?? 0);
const threshold = Number(Threshold ?? 0);
const operatorLabel = OperatorName?.value?.label ?? "-";

const openRows = await eventSys.get(`${eventPath}*`, "*", "*", "open", {}, { limit: 1 });

if (speed > threshold) {

  asset.set(MachineAlarmAttribute.path, `Oii ${operatorLabel} bahaya!`);

  if (openRows.length === 0) {
    await eventSys.open(eventPath,nowTs,{operatorLabel,speed,threshold},`Machine speed ${speed} > threshold ${threshold}`,"low",{ speed, threshold, operatorLabel, state: "open" });
  }

} else {

  asset.set(MachineAlarmAttribute.path, "No alarm.");

  if (openRows.length > 0) {
    await eventSys.close(`${eventPath}*`,nowTs,`Machine speed ${speed} <= threshold ${threshold}`,{ speed, threshold, operatorLabel, state: "close" });
  }
}

send(msg);

// VARIABLE BINDINGS
const jobLifecycleAttribute = JobLifecycleAttribute?.value || "-";
const workOrderAttribute = WorkOrderAttribute?.value || "-";
const operatorAttribute = OperatorAttribute?.value || "-";
const timestamp = Timestamp?.value || helpers.now();
const assetPath = AssetPath || "-";
const alarmAttributePath = AlarmAttribute?.path || "-";
const jobLifecycleAttributePath = JobLifecycleAttribute?.path || "-";
const jobActivityAttributePath = JobActivityAttribute?.path || "-";
const workOrderAttributePath = WorkOrderAttribute?.path || "-";

const renderPath = (template, vars = {}) => {
  return String(template || "")
    .replaceAll("{assetPath}", String(vars.assetPath ?? assetPath))
    .replaceAll("{workOrder}", String(vars.workOrder ?? workOrderAttribute))
    .replaceAll("{activity}", String(vars.activity ?? "*"));
};

const lifecycleRunningEventPath = renderPath(LifecycleRunningEventPathTemplate);
const openedEvents = await eventSys.get(lifecycleRunningEventPath, "*", "*", "open", {}, { limit: 1 });
const templateVars = {
  assetPath,
  workOrder: workOrderAttribute,
  operator: operatorAttribute,
  timestamp
};

helpers.log("event mulai:", jobLifecycleAttribute);

if (!["load", "unload", "complete"].includes(String(jobLifecycleAttribute).trim().toLowerCase())) {
  helpers.log("--- bukan load/unload");
  return;
}

helpers.log("--- terdeteksi load/unload");

if (workOrderAttribute === "-" || workOrderAttribute === "" || workOrderAttribute === null) {
  asset.set(alarmAttributePath, "!!!Work order is empty!!!");
  asset.set(jobLifecycleAttributePath, "-");
  msg.payload = "alarm: work order is empty";
  send(msg);
} else {
  asset.set(alarmAttributePath, "-");

  if (String(jobLifecycleAttribute).trim().toLowerCase() === "load") {
    if (openedEvents.length === 0) {
      asset.setMany(
        [
          { path: PaperConsumedIdle.path, value: 0 },
          { path: PaperConsumedProduction.path, value: 0 },
          { path: PaperConsumedSetup.path, value: 0 },
          { path: TotalIdleTime.path, value: 0 },
          { path: TotalProductionTime.path, value: 0 },
          { path: TotalSetupTime.path, value: 0 },
          { path: JobActivityCategoryAttribute.path, value: "-" }
        ]
      );

      await eventSys.openTemplate("job_lifecycle_running", {
        vars: templateVars,
        notes: `${workOrderAttribute} loaded`
      });

      msg.payload = "event opened";
      send(msg);
    }
  } else if (String(jobLifecycleAttribute).trim().toLowerCase() === "unload") {
    if (openedEvents.length > 0) {
      await eventSys.closeTemplate("job_lifecycle_running", {
        vars: templateVars,
        notes: `${workOrderAttribute} unloaded`
      });

      await eventSys.closeTemplate("job_activity", {
        vars: { ...templateVars, activity: "*" },
        notes: `${workOrderAttribute} unloaded`
      });

      asset.set(workOrderAttributePath, "-");
      asset.set(jobLifecycleAttributePath, "-");
      asset.set(jobActivityAttributePath, "-");
      asset.set(JobActivityCategoryAttribute.path, "-");

      msg.payload = "event closed";
      send(msg);
    }
  } else if (String(jobLifecycleAttribute).trim().toLowerCase() === "complete") {
    if (openedEvents.length > 0) {
      await eventSys.closeTemplate("job_lifecycle_running", {
        vars: templateVars,
        notes: `${workOrderAttribute} completed`
      });

      await eventSys.closeTemplate("job_activity", {
        vars: { ...templateVars, activity: "*" },
        notes: `${workOrderAttribute} completed`
      });

      asset.set(workOrderAttributePath, "-");
      asset.set(jobLifecycleAttributePath, "-");
      asset.set(jobActivityAttributePath, "-");

      msg.payload = "event closed";
      send(msg);
    }
  }
